// cappedHolds — laws/haskell_extract.lawspec:6152.
func (lawSpecDefinitions) CappedHolds(
	symbols map[string]*LawSpecSymbol,
	haskellParser HaskellParser,
	rs []Row,
	cap_ *LawSpecBigInt,
	given Env,
	env Env,
) bool {
	return lsNativeContext("assayxport.haskell.extract::cappedHolds", func() bool {
		schema := _lawSpecDefinitionSchema
		bits := 64
		lsInstallHandlers(symbols, map[string]any{"assayxport.haskell.extract::ability::HaskellParser": haskellParser})
		rsCodec := lsListCodec(schema, bits, lawSpecRowCodec(schema, bits, symbols), symbols)
		rsValue := rsCodec.fromNative(rs)
		cap_Codec := lsScalarCodec[*LawSpecBigInt](schema, bits, "Integer")
		cap_Value := cap_Codec.fromNative(cap_)
		givenCodec := lawSpecEnvCodec(schema, bits, symbols)
		givenValue := givenCodec.fromNative(given)
		envCodec := lawSpecEnvCodec(schema, bits, symbols)
		envValue := envCodec.fromNative(env)
		resultCodec := lsScalarCodec[bool](schema, bits, "Bool")
		result := lawSpecEvaluateCappedHolds(symbols, rsValue, cap_Value, givenValue, envValue)
		return resultCodec.toNative(result)
	})
}

