// fixtureBuildHolds — laws/haskell_extract.lawspec:5073.
func (lawSpecDefinitions) FixtureBuildHolds(
	symbols map[string]*LawSpecSymbol,
	haskellParser HaskellParser,
	i *LawSpecBigInt,
) bool {
	return lsNativeContext("assayxport.haskell.extract::fixtureBuildHolds", func() bool {
		schema := _lawSpecDefinitionSchema
		bits := 64
		lsInstallHandlers(symbols, map[string]any{"assayxport.haskell.extract::ability::HaskellParser": haskellParser})
		iCodec := lsScalarCodec[*LawSpecBigInt](schema, bits, "Integer")
		iValue := iCodec.fromNative(i)
		resultCodec := lsScalarCodec[bool](schema, bits, "Bool")
		result := lawSpecEvaluateFixtureBuildHolds(symbols, iValue)
		return resultCodec.toNative(result)
	})
}

